-- all41 app catalog: 119 ready-to-build templates across 16 categories.
-- Generated from a typed source (scratchpad/catalog/*.mjs) and validated: placeholders ⇄ config keys, schemas ∈ {answer,report,briefing,content_pack},
-- step kinds ∈ {search,crawl,llm}, llm task_types ∈ the engine list, unique slugs. Roster apps (Master Plan §11) sit at sort_order 10–14.
-- Safe to re-run: upserts on slug.
insert into public.mini_apps (slug, name, description, category, icon, who_for, tags, brief_template, config_schema, workflow_def, est_credit_cost, is_published, sort_order) values
